from datetime import datetime

def latest_by_user(events):
    latest = {}
    for event in events:
        key = event["user_id"]
        current = datetime.fromisoformat(event["timestamp"])
        previous = latest.get(key)
        if previous is None or current >= datetime.fromisoformat(previous["timestamp"]):
            latest[key] = event
    return list(latest.values())

