def test_merge_settings_does_not_mutate_inputs():
    defaults = {"theme": "light", "volume": 50}
    overrides = {"theme": "dark"}
    defaults_before = defaults.copy()
    overrides_before = overrides.copy()

    result = merge_settings(defaults, overrides)

    assert result == {"theme": "dark", "volume": 50}
    assert defaults == defaults_before
    assert overrides == overrides_before
    assert result is not defaults
    assert result is not overrides

def chunks(items, size):
    if size <= 0:
        raise ValueError("size must be positive")
    return [items[i:i + size] for i in range(0, len(items), size)]

function uniqueById(items) {
  const seen = new Set();
  return items.filter(item => {
    if (seen.has(item.id)) return false;
    seen.add(item.id);
    return true;
  });
}

